const meshes=new Map();function syncMeshes(){for(const c of sim.citizens){if(!meshes.has(c.id)){const texture=new T.CanvasTexture(avatarCanvas(c.id));texture.magFilter=T.NearestFilter;texture.minFilter=T.NearestFilter;texture.colorSpace=T.SRGBColorSpace;const sprite=new T.Sprite(new T.SpriteMaterial({map:texture,alphaTest:.1}));sprite.scale.set(2.4,3,1);sprite.userData.id=c.id;scene.add(sprite);meshes.set(c.id,sprite)}}for(const [id,m]of meshes)if(!sim.citizens.some(c=>c.id===id)){scene.remove(m);m.material.map.dispose();m.material.dispose();meshes.delete(id)}}syncMeshes();
