function pan(dx,dy){const scale=distance*.0012;target.x+=(-dx*Math.cos(angle)-dy*Math.sin(angle))*scale;target.z+=(dx*Math.sin(angle)-dy*Math.cos(angle))*scale;target.x=T.MathUtils.clamp(target.x,-32,32);target.z=T.MathUtils.clamp(target.z,-28,28);following=false;}
