renderer.domElement.addEventListener('pointermove',e=>{if(!down)return;let dx=e.clientX-down.x,dy=e.clientY-down.y;if(Math.hypot(e.clientX-down.startX,e.clientY-down.startY)>5)down.moved=true;if(down.button===2){angle-=dx*.006;elevation=Math.max(.35,Math.min(1.3,elevation+dy*.004))}else pan(dx,dy);down.x=e.clientX;down.y=e.clientY});
