function drawMap(){const g=$('minimap').getContext('2d');g.fillStyle='#91ca78';g.fillRect(0,0,192,168);g.fillStyle='#55bedc';g.fillRect(157,0,21,168);g.fillStyle='#e9d398';for(const z of [-8,8])g.fillRect(0,(z+28)*3-4,157,8);for(const x of [-20,-4,12])g.fillRect((x+32)*3-4,0,8,168);for(const c of sim.citizens){g.fillStyle=c.id===selected?'#fff3a3':['#d85365','#527cc9','#9361be'][c.faction];g.fillRect((c.x+32)*3-2,(c.z+28)*3-2,4,4)}g.strokeStyle='#253756';g.lineWidth=2;g.strokeRect((target.x+32)*3-13,(target.z+28)*3-10,26,20)}
function select(id){selected=id;following=false;$('inspector').classList.remove('hidden');$('drawer').classList.add('hidden');drawer='';update()}
function update(){const citizens=sim.citizens;$('clock').textContent=`DAY ${Math.floor(sim.day)} · ${String(Math.floor((sim.day%1)*24)).padStart(2,'0')}:00`;$('population').textContent=citizens.length;$('happiness').textContent=`${Math.round(citizens.reduce((s,c)=>s+(c.energy+c.hunger+c.social)/3,0)/Math.max(1,citizens.length))}%`;$('treasury').textContent=Math.round(sim.treasury).toLocaleString();$('peace').textContent=sim.tension>65?'Conflict':sim.tension>40?'Tense':'Peace';$('weatherLabel').textContent=sim.weather==='Rain'?'☂ RAIN':'☀ CLEAR';$('tax').textContent=`${Math.round(sim.tax*100)}% TAX`;$('government').textContent=`${citizens.find(c=>c.id===sim.leader)?.name||'Vacant council'} · Food reserve ${Math.floor(sim.food)} · Price ¤${(1+Math.max(0,(100-sim.food)/30)).toFixed(1)}`;$('events').innerHTML=sim.events.slice(0,5).map(e=>`<div class="event"><time>DAY ${e.day}</time>${e.text}</div>`).join('');const c=citizens.find(c=>c.id===selected);if(!c){$('detail').innerHTML='<p>This citizen has passed away. Choose another from Citizens.</p>';return}if(!c.brain?.trace)infer(c,sim);const mood=c.hunger<30?'Hungry':c.energy<30?'Sleepy':c.social>65?'Connected':'Curious';const oldScroll=$('inspector').scrollTop;$('detail').innerHTML=`<div class="citizen-card"><img src="${portrait(c.id)}" alt="${c.name}'s unique avatar"><div><span class="dex-number">CITIZEN #${String(c.id+1).padStart(3,'0')}</span><h2>${c.name}</h2><div class="sub">${c.job} · Lv. ${Math.floor(c.age)} · ${factions[c.faction]}</div></div></div><div class="citizen-actions"><span class="mood">● ${mood} · ${c.action}</span><button id="followCitizen">${following?'■ Unfollow':'◎ Follow'}</button></div><div class="section-title">LIVE NEURAL NETWORK <span>LEARNING</span></div><div class="network">${neuralView(c)}</div><div class="goal-card"><b>LONG-TERM QUEST</b><p>${c.goal}</p></div><div class="quote">${c.brain.history.slice(0,3).map(h=>`${h.action}: reward ${h.reward>=0?'+':''}${h.reward.toFixed(3)}`).join(' → ')}</div><div class="section-title">NEEDS & PERSONALITY <span>¤${Math.floor(c.wealth)}</span></div>${['hunger','energy','social','empathy','ambition','caution','aggression'].map(k=>`<div class="barrow"><span>${k==='hunger'?'Nourishment':k[0].toUpperCase()+k.slice(1)}</span><span>${Math.round(c[k])}%</span></div><div class="bar"><i style="width:${c[k]}%"></i></div>`).join('')}<div class="divider"></div><div class="section-title">HOUSEHOLD</div><p class="mem">${c.partner!==null?citizens.find(p=>p.id===c.partner)?.name||'Partner deceased':'No partner'} · ${c.children} children</p><div class="section-title">MEMORY VAULT</div>${c.memories.slice(0,4).map(m=>`<p class="mem">${m}</p>`).join('')}`;$('followCitizen').onclick=()=>{following=!following;if(following){target.set(c.x,0,c.z);distance=42}update()};$('inspector').scrollTop=oldScroll;drawMap();}

function showPeople(){drawer='people';$('drawer').classList.remove('hidden');$('drawer').innerHTML='<div class="section-title">CITIZEN DIRECTORY <span>'+sim.citizens.length+' MINDS</span></div><input id="search" placeholder="Find a citizen or profession…" aria-label="Find a citizen"><div id="list"></div>';$('search').oninput=filter;filter()}
function filter(){const q=$('search').value.toLowerCase();$('list').innerHTML='';for(const c of sim.citizens.filter(c=>(c.name+' '+c.job).toLowerCase().includes(q))){const b=document.createElement('button');b.className='person';b.innerHTML=`<img src="${portrait(c.id)}" alt=""><span>${c.name}<small>${c.job}</small></span>`;b.onclick=()=>{select(c.id);target.set(c.x,0,c.z);distance=40};$('list').append(b)}}
document.querySelectorAll('[data-speed]').forEach(b=>b.onclick=()=>{speed=+b.dataset.speed;document.querySelectorAll('[data-speed]').forEach(x=>x.classList.toggle('active',x===b))});$('close').onclick=()=>$('inspector').classList.add('hidden');$('orbit').onclick=()=>{auto=!auto;$('orbit').classList.toggle('active',auto)};$('home').onclick=()=>{following=false;target.set(0,0,0);distance=92;angle=.78;elevation=.76};$('people').onclick=()=>{if(drawer==='people'){drawer='';$('drawer').classList.add('hidden')}else showPeople()};$('catalyst').onclick=()=>{if(drawer==='env'){drawer='';$('drawer').classList.add('hidden');return}drawer='env';$('drawer').classList.remove('hidden');$('drawer').innerHTML='<div class="section-title">ENVIRONMENTAL CATALYSTS</div><p class="mem">Change the conditions. Observe their choices.</p>';for(const [name,desc]of [['Clear','Sunlight returns to the city'],['Rain','Five days of rain improve harvests'],['Abundance','Add 250 food to the granary'],['Scarcity','Crop failure removes 80% of reserves'],['Discovery','New ideas raise ambition and treasury']]){const b=document.createElement('button');b.className='env';b.innerHTML=name+'<small>'+desc+'</small>';b.onclick=()=>{sim.catalyst(name);update()};$('drawer').append(b)}};$('help').onclick=()=>$('guide').showModal();$('guideClose').onclick=()=>$('guide').close();$('reset').onclick=()=>{if(confirm('Replace your saved civilization with a new world?')){sim=new Simulation();selected=0;syncMeshes();update();$('guide').close();save()}};
function save(){try{localStorage.setItem('freecity-v1',JSON.stringify(sim))}catch{$('toast').textContent='Browser storage unavailable. This session cannot be saved.';$('toast').style.display='block'}}setInterval(save,10000);addEventListener('pagehide',save);let prior=performance.now(),acc=0;function frame(now){requestAnimationFrame(frame);let dt=Math.min((now-prior)/1000,.1);prior=now;acc+=dt*speed;let count=0;while(acc>.12&&count<40){sim.step();acc-=.12;count++}if(count)syncMeshes();for(const c of sim.citizens){let dx=c.tx-c.x,dz=c.tz-c.z,l=Math.hypot(dx,dz),step=Math.min(l,dt*speed*1.3);if(l>.1){c.x+=dx/l*step;c.z+=dz/l*step}const m=meshes.get(c.id);m.position.set(c.x,1.5+Math.sin(now*.009+c.id)*.1*(speed&&l>.1?1:0),c.z);const size=c.age<18?.75:1;m.scale.set(2.4*size,3*size,1)}const c=sim.citizens.find(c=>c.id===selected);ring.visible=!!c;if(c)ring.position.set(c.x,.24,c.z);if(following&&c)target.lerp(new T.Vector3(c.x,0,c.z),Math.min(1,dt*5));if(keys.has('w')||keys.has('arrowup'))pan(0,dt*260);if(keys.has('s')||keys.has('arrowdown'))pan(0,-dt*260);if(keys.has('a')||keys.has('arrowleft'))pan(dt*260,0);if(keys.has('d')||keys.has('arrowright'))pan(-dt*260,0);if(keys.has('q'))angle-=dt;if(keys.has('e'))angle+=dt;if(auto)angle+=dt*.06;camera.position.set(target.x+Math.sin(angle)*Math.cos(elevation)*distance,Math.sin(elevation)*distance,target.z+Math.cos(angle)*Math.cos(elevation)*distance);camera.lookAt(target);sun.intensity=sim.weather==='Rain'?1.3:3;if(now-lastUI>650){update();lastUI=now}for(let i=0;i<sparkles.length;i++)sparkles[i].position.x=23+(i%3)+Math.sin(now*.001+i)*.4;renderer.render(scene,camera)}update();requestAnimationFrame(frame);
